import{_ as e,c as s,o as p,b0 as t}from"./chunks/framework.JcZxIv1X.js";const n="/computer-docs/assets/image-20251014093613133.Dp40NF5E.png",o="/computer-docs/assets/image-20251014093809014.BsaBpoPR.png",i="/computer-docs/assets/image-20251014093910143.DSjHBKxp.png",l="/computer-docs/assets/image-20251014101756904.6UUiW9yi.png",r="/computer-docs/assets/image-20251021105326996.B6laJ_XO.png",c="/computer-docs/assets/image-20251014104556855.CBYG9D4c.png",d="/computer-docs/assets/image-20251014105834777.6yFt-P1q.png",m="/computer-docs/assets/image-20251014110025106.BwqdlY-b.png",b="/computer-docs/assets/image-20251014110039851.tiw9uQmX.png",u="/computer-docs/assets/image-20251014113202224.S6Uj_b5p.png",h="/computer-docs/assets/image-20251014113353657.22ZXikAx.png",g="/computer-docs/assets/image-20251014113837577.U46LwDGW.png",P="/computer-docs/assets/689056-20211213001833220-675196650.CyUwfmsR.png",C="/computer-docs/assets/aef56facfac63cd43ee1b7f419e9b276.Dw7YQiC_.png",_="/computer-docs/assets/36747aa3798d9ba53648178fb2bef8b1.CP9XIMoL.png",U="/computer-docs/assets/49f6c3b9398463de9581f849fd37c599.DyOyXtz4.png",q="/computer-docs/assets/ffb460996e1def2e66a6f22b0c48d9b8.D2fzag-s.png",D=JSON.parse('{"title":"LV001-第1章-基础知识","description":null,"frontmatter":{"title":"LV001-第1章-基础知识","date":"2025-10-21T11:43:29.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/assembly/assembly/chapter/126b0eeb7bd93b40bb9f95d1","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-10-21T11:43:29.948Z","fulluuid":"0bb9f95d15fc4327800476238d8a3439","useduuid":"0bb9f95d1"}},"headers":[],"relativePath":"sdoc/assembly/assembly/chapter/126b0eeb7bd93b40bb9f95d1.md","filePath":"sdoc/01-Assembly/10-汇编语言/01-各个章节/LV001-第1章-基础知识.md","lastUpdated":1767424849000}'),B={name:"sdoc/assembly/assembly/chapter/126b0eeb7bd93b40bb9f95d1.md"};function f(k,a,v,y,S,x){return p(),s("div",null,[...a[0]||(a[0]=[t('<h1 id="lv001-第1章-基础知识" tabindex="-1">LV001-第1章-基础知识 <a class="header-anchor" href="#lv001-第1章-基础知识" aria-label="Permalink to &quot;LV001-第1章-基础知识&quot;">​</a></h1><p>汇编语言是直接在硬件之上工作的编程语言，我们首先要了解硬件系统的结构，才能有效地应用汇编语言对其编程。</p><p>在汇编课程中我们不对硬件系统进行全面和深入的研究，关于 PC 机及 CPU 物理结构和编程结构的全面研究，在《微机原理与接口》中进行；对于计算机一般的结构、功能、性能的研究在一门称为《组成原理》的理论层次更高的课程中进行。汇编课程的研究重点放在 <strong>如何利用硬件系统的编程结构和指令集有效灵活地控制系统进行工作</strong>。</p><h2 id="_1-1-机器语言" tabindex="-1">1.1 机器语言 <a class="header-anchor" href="#_1-1-机器语言" aria-label="Permalink to &quot;1.1 机器语言&quot;">​</a></h2><p>机器语言是机器指令的集合。机器指令展开来讲就是一台机器可以正确执行的命令。电子计算机的机器指令是一列二进制数字。计算机将之转变为一列高低电平, 以使计算机的电子器件受到驱动，进行运算。</p><p>上面所说的计算机指的是可以执行机器指令, 进行运算的机器。这是早期计算机的概念。现在, 在我们常用的 PC 机中, 有一个芯片来完成上面所说的计算机的功能。这个芯片就是我们常说的 CPU(Cesntral Processing Unit, 中央处理单元), CPU 是一种微处理器。以后我们提到的计算机是指由 CPU 和其他受 CPU 直接或间接控制的芯片、器件、设备组成的计算机系统, 比如我们最常见的 PC 机。</p><p>每一种微处理器, 由于硬件设计和内部结构的不同, 就需要用不同的电平脉冲来控制, 使它工作。所以每一种微处理器都有自己的机器指令集, 也就是机器语言。早期的程序设计均使用机器语言。程序员们将用 0、1 数字编成的程序代码打在纸带或卡片上,1 打孔,0 不打孔, 再将程序通过纸带机或卡片机输入计算机, 进行运算。</p><p>应用 8086CPU 完成运算 s = 768+12288-1280, 机器码如下。</p><p><img src="'+n+'" alt="image-20251014093613133"></p><p>假如将程序错写成以下这样, 请你找出错误。</p><p><img src="'+o+'" alt="image-20251014093809014"></p><p>书写和阅读机器码程序不是一件简单的工作，要记住所有抽象的二进制码。上面只是一个非常简单的小程序，就暴露了机器码的晦涩难懂和不易查错。写如此小的一个程序尚且如此，实际上一个有用的程序至少要有几十行机器码，那么，情况将怎么样呢？在显示器上输出 &quot;welcome to masm&quot;，机器码如下。</p><p><img src="'+i+`" alt="image-20251014093910143"></p><p>看到这样的程序, 你有什么感想?如果程序里有一个 &quot;1&quot; 被误写为 &quot;0&quot;, 又如何去查找呢?</p><h2 id="_1-2-汇编语言的产生" tabindex="-1">1.2 汇编语言的产生 <a class="header-anchor" href="#_1-2-汇编语言的产生" aria-label="Permalink to &quot;1.2 汇编语言的产生&quot;">​</a></h2><p>早期的程序员们很快就发现了使用机器语言带来的麻烦, 它是如此难于辨别和记忆, 给整个产业的发展带来了障碍。于是汇编语言产生了。</p><p>汇编语言的主体是汇编指令。汇编指令和机器指令的差别在于指令的表示方法上。汇编指令是机器指令便于记忆的书写格式。</p><p>例如: 机器指令 1000100111011000 表示把寄存器 BX 的内容送到 AX 中。汇编指令则写成 mov ax, bx。这样的写法与人类语言接近, 便于阅读和记忆。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>操作   : 寄存器 BX 的内容送到 AX 中</span></span>
<span class="line"><span>机器指令: 1000100111011000</span></span>
<span class="line"><span>汇编指令: mov ax, bx</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><blockquote><p>Tips：寄存器, 简单地讲是 CPU 中可以存储数据的器件, 一个 CPU 中有多个寄存器。AX 是其中一个寄存器的代号, BX 是另一个寄存器的代号。更详细的内容我们在以后的课程中将会讲到。</p></blockquote><p>此后, 程序员们就用汇编指令编写源程序。可是, 计算机能读懂的只有机器指令, 那么如何让计算机执行程序员用汇编指令编写的程序呢?这时, 就需要有一个能够将汇编指令转换成机器指令的翻译程序, 这样的程序我们称其为编译器。程序员用汇编语言写出源程序, 再用汇编编译器将其编译为机器码, 由计算机最终执行。图 1.1 描述了这个工作过程。</p><p><img src="`+l+`" alt="image-20251014101756904"></p><h2 id="_1-3-汇编语言的组成" tabindex="-1">1.3 汇编语言的组成 <a class="header-anchor" href="#_1-3-汇编语言的组成" aria-label="Permalink to &quot;1.3 汇编语言的组成&quot;">​</a></h2><p>汇编语言发展至今, 有以下 3 类指令组成。</p><p>（1）汇编指令: 机器码的助记符, 有对应的机器码。</p><p>（2）伪指令: 没有对应的机器码, 由编译器执行, 计算机并不执行。</p><p>（3）其他符号: 如 <code>+</code>、<code>-</code>、<code>*</code>、<code>/</code> 等, 由编译器识别, 没有对应的机器码。</p><p>汇编语言的核心是汇编指令, 它决定了汇编语言的特性。</p><h2 id="_1-4-存储器" tabindex="-1">1.4 存储器 <a class="header-anchor" href="#_1-4-存储器" aria-label="Permalink to &quot;1.4 存储器&quot;">​</a></h2><p>CPU 是计算机的核心部件，它控制整个计算机的运作并进行运算。要想让一个 CPU 工作，就必须向它提供指令和数据。指令和数据在 <strong>存储器</strong> 中存放，也就是我们平时所说的 <strong>内存</strong>。在一台 PC 机中内存的作用仅次于 CPU，离开了内存，性能再好的 CPU 也无法工作。磁盘不同于内存，磁盘上的数据或程序如果不读到内存中，就无法被 CPU 使用。要灵活地利用汇编语言编程，我们首先要了解 CPU 是如何从内存中读取信息，以及向内存中写入信息的。</p><h2 id="_1-5-指令和数据" tabindex="-1">1.5 指令和数据 <a class="header-anchor" href="#_1-5-指令和数据" aria-label="Permalink to &quot;1.5 指令和数据&quot;">​</a></h2><p>指令和数据是应用上的概念。<strong>在内存或磁盘上, 指令和数据没有任何区别, 都是二进制信息</strong>。CPU 在工作的时候把有的信息看作指令, 有的信息看作数据, 为同样的信息赋予了不同的意义。就像围棋的棋子, 在棋盒里的时候没有任何区别, 在对弈的时候就有了不同的意义。</p><p>例如, 内存中的二进制信息 1000100111011000, 计算机可以把它看作大小为 89D8H 的数据来处理, 也可以将其看作指令 mov ax, bx 来执行。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1000100111011000 --&gt; 89D8H(数据)</span></span>
<span class="line"><span>1000100111011000 --&gt; mov ax,bx (程序)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="_1-6-存储单元" tabindex="-1">1.6 存储单元 <a class="header-anchor" href="#_1-6-存储单元" aria-label="Permalink to &quot;1.6 存储单元&quot;">​</a></h2><p><img src="`+r+'" alt="image-20251021105326996"></p><p>存储器被划分成若干个存储单元, 每个存储单元从 0 开始顺序编号, 例如一个存储器有 128 个存储单元, 编号从 0~127, 如图 1.2 所示。</p><p>那么一个存储单元能存储多少信息呢?我们知道电子计算机的最小信息单位是 bit(音译为比特), 也就是一个二进制位。8 个 bit 组成一个 Byte, 也就是通常讲的一个字节。微型机存储器的存储单元可以存储一个 Byte, 即 8 个二进制位。一个存储器有 128 个存储单元, 它可以存储 128 个 Byte。</p><p>微机存储器的容量是以字节为最小单位来计算的。对于拥有 128 个存储单元的存储器, 我们可以说, 它的容量是 128 个字节。</p><p>对于大容量的存储器一般还用以下单位来计量容量(以下用 B 来代表 Byte)：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1KB=1024B 1MB=1024KB 1GB=1024MB 1TB=1024GB</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>磁盘的容量单位同内存的一样, 实际上以上单位是微机中常用的计量单位。</p><h2 id="_1-7-cpu-对存储器的读写" tabindex="-1">1.7 CPU 对存储器的读写 <a class="header-anchor" href="#_1-7-cpu-对存储器的读写" aria-label="Permalink to &quot;1.7 CPU 对存储器的读写&quot;">​</a></h2><p>以上讲到, 存储器被划分成多个存储单元, 存储单元从零开始顺序编号。这些编号可以看作存储单元在存储器中的地址。就像一条街, 每个房子都有门牌号码。</p><p>CPU 要从内存中读数据, 首先要指定存储单元的地址。也就是说它要先确定它要读取哪一个存储单元中的数据。就像在一条街上找人, 先要确定他住在哪个房子里。</p><p>另外, 在一台微机中, 不只有存储器这一种器件。CPU 在读写数据时还要指明, 它要对哪一个器件进行操作, 进行哪种操作, 是从中读出数据, 还是向里面写入数据。</p><p>可见, CPU 要想进行数据的读写, 必须和外部器件(标准的说法是芯片)进行下面 3 类信息的交互。</p><ul><li><p>存储单元的地址(地址信息);</p></li><li><p>器件的选择, 读或写的命令(控制信息);</p></li><li><p>读或写的数据(数据信息)。</p></li></ul><p>那么 CPU 是通过什么将地址、数据和控制信息传到存储器芯片中的呢?电子计算机能处理、传输的信息都是电信号, 电信号当然要用导线传送。在计算机中专门有连接 CPU 和其他芯片的导线, 通常称为 <strong>总线</strong>。总线从物理上来讲, 就是一根根导线的集合。根据传送信息的不同, 总线从逻辑上又分为 3 类, <strong>地址总线</strong>、<strong>控制总线</strong> 和 <strong>数据总线</strong>。</p><p>CPU 从 3 号单元中读取数据的过程(见图 1.3)如下。</p><p><img src="'+c+`" alt="image-20251014104556855"></p><p>（1）CPU 通过地址线将地址信息 3 发出。</p><p>（2）CPU 通过控制线发出内存读命令, 选中存储器芯片, 并通知它, 将要从中读取数据。</p><p>（3）存储器将 3 号单元中的数据 8 通过数据线送入 CPU。</p><p>写操作与读操作的步骤相似。如向 3 号单元写入数据 26。</p><p>（1）CPU 通过地址线将地址信息 3 发出。</p><p>（2）CPU 通过控制线发出内存写命令, 选中存储器芯片, 并通知它, 要向其中写入数据。</p><p>（3）CPU 通过数据线将数据 26 送入内存的 3 号单元中。</p><p>从上面我们知道了 CPU 是如何进行数据读写的。可是, 如何命令计算机进行数据的读写呢?</p><p>要让一个计算机或微处理器工作, 应向它输入能够驱动它进行工作的电平信息(机器码)。</p><p>对于 8086CPU, 下面的机器码, 能够完成从 3 号单元读数据。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>机器码: 101000010000001100000000</span></span>
<span class="line"><span>含义:   从 3 号单元读取数据送入寄存器 AX</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>CPU 接收这条机器码后将完成我们上面所述的读写工作。机器码难于记忆, 用汇编指令来表示, 情况如下。</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>机器码:       10100001 00000011 00000000</span></span>
<span class="line"><span>对应的汇编指令: MOV AX, [3]</span></span>
<span class="line"><span>含义:         传送 3 号单元的内容入 AX</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="_1-8-地址总线" tabindex="-1">1.8 地址总线 <a class="header-anchor" href="#_1-8-地址总线" aria-label="Permalink to &quot;1.8 地址总线&quot;">​</a></h2><p>现在我们知道, CPU 是通过地址总线来指定存储器单元的。可见地址总线上能传送多少个不同的信息, CPU 就可以对多少个存储单元进行寻址。</p><p>现假设, 一个 CPU 有 10 根地址总线, 让我们来看一下它的寻址情况。我们知道, 在电子计算机中, 一根导线可以传送的稳定状态只有两种, 高电平或是低电平。用二进制表示就是 1 或 0,10 根导线可以传送 10 位二进制数据。而 10 位二进制数可以表示多少个不同的数据呢?2 的 10 次方个。最小数为 0, 最大数为 1023。</p><p>图 1.4 展示了一个具有 10 根地址线的 CPU 向内存发出地址信息 11 时 10 根地址线上传送的二进制信息。考虑一下, 读访问地址为 12、13、 14 等的内存单元时, 地址总线上传送的内容是什么?</p><p>一个 CPU 有 N 根地址线, 则可以说这个 CPU 的地址总线的宽度为 N。这样的 CPU 最多可以寻找 <strong>2 的 N 次方</strong> 个内存单元。</p><p><img src="`+d+'" alt="image-20251014105834777"></p><h2 id="_1-9-数据总线" tabindex="-1">1.9 数据总线 <a class="header-anchor" href="#_1-9-数据总线" aria-label="Permalink to &quot;1.9 数据总线&quot;">​</a></h2><p>CPU 与内存或其他器件之间的数据传送是通过数据总线来进行的。数据总线的宽度决定了 CPU 和外界的数据传送速度。8 根数据总线一次可传送一个 8 位二进制数据(即一个字节)。16 根数据总线一次可传送两个字节。</p><p>8088CPU 的数据总线宽度为 8，8086CPU 的数据总线宽度为 16。我们来分别看一下它们向内存中写入数据 89D8H 时, 是如何通过数据总线传送数据的。图 1.5 展示了 8088CPU 数据总线上的数据传送情况; 图 1.6 展示了 8086CPU 数据总线上的数据传送情况。</p><table><tbody><tr><td width="50%" align="center"><img src="'+m+'"></td> <td width="50%" align="center"><img src="'+b+'"></td></tr></tbody></table><p>8086 有 16 根数据线, 可一次传送 16 位数据, 所以可一次传送数据 89D8H; 而 8088 只有 8 根数据线, 一次只能传 8 位数据, 所以向内存写入数据 89D8H 时需要进行两次数据传送。</p><h2 id="_1-10-控制总线" tabindex="-1">1.10 控制总线 <a class="header-anchor" href="#_1-10-控制总线" aria-label="Permalink to &quot;1.10 控制总线&quot;">​</a></h2><p>CPU 对外部器件的控制是通过控制总线来进行的。在这里控制总线是个总称，控制总线是一些不同控制线的集合。有多少根控制总线，就意味着 CPU 提供了对外部器件的多少种控制。所以，<strong>控制总线的宽度决定了 CPU 对外部器件的控制能力</strong>。</p><p>前面所讲的内存读或写命令是由几根控制线综合发出的，其中有一根称为 &quot;读信号输出&quot; 的控制线负责由 CPU 向外传送读信号，CPU 向该控制线上输出低电平表示将要读取数据：有一根称为 &quot;写信号输出&quot; 的控制线则负责传送写信号。</p><h2 id="_1-a-检测点与小结" tabindex="-1">1.A 检测点与小结 <a class="header-anchor" href="#_1-a-检测点与小结" aria-label="Permalink to &quot;1.A 检测点与小结&quot;">​</a></h2><h3 id="_1-1-1-10-小结" tabindex="-1">1.1-1.10 小结 <a class="header-anchor" href="#_1-1-1-10-小结" aria-label="Permalink to &quot;1.1-1.10 小结&quot;">​</a></h3><blockquote><p>(1) 汇编指令是机器指令的助记符，同机器指令一一对应。</p><p>(2) 每一种 CPU 都有自己的汇编指令集。</p><p>(3) CPU 可以直接使用的信息在存储器中存放。</p><p>(4) 在存储器中指令和数据没有任何区别，都是二进制信息。</p><p>(5) 存储单元从零开始顺序编号。</p><p>(6) 一个存储单元可以存储 8 个 bit，即 8 位二进制数。</p><p>(7) 1Byte = 8bit 1KB = 1024B 1MB = 1024KB 1GB = 1024MB。</p><p>(8) 每一个 CPU 芯片都有许多 <strong>管脚</strong>，这些管脚和总线相连。也可以说，这些管脚引出总线。一个 CPU 可以引出 3 种总线的宽度标志了这个 CPU 的不同方面的性能：</p><ul><li><p>地址总线的宽度决定了 CPU 的寻址能力；</p></li><li><p>数据总线的宽度决定了 CPU 与其他器件进行数据传送时的一次数据传送量;</p></li><li><p>控制总线的宽度决定了 CPU 对系统中其他器件的控制能力。</p></li></ul><p>在汇编课程中，我们从功能的角度介绍了 3 类总线，对实际的连接情况不做讨论。</p></blockquote><h3 id="检测点-1-1" tabindex="-1">检测点 1.1 <a class="header-anchor" href="#检测点-1-1" aria-label="Permalink to &quot;检测点 1.1&quot;">​</a></h3><p>(1) 1 个 CPU 的寻址能力为 8KB，那么它的地址总线的宽度为 <code>13</code>。</p><p>(2) 1KB 的存储器有 <code>1024</code> 个存储单元。存储单元的编号从 <code>0</code> 到 <code>1023</code></p><p>(3) 1KB 的存储器可以存储 <code>8192</code> 个 bit, <code>1024</code> 个 Byte。</p><p>(4) 1GB、1MB、1KB 分别是 <code>2^30、2^20、2^10</code> Byte.</p><p>(5) 8080、8088、80286、80386 的地址总线宽度分别为 16 根、20 根、24 根、32 根，则它们的寻址能力分别为：</p><p><code>64</code>(KB)、<code>1</code>(MB)、<code>16</code>(MB)、<code>4</code>(GB)。</p><p>(6) 8080、8088、8086、80286、80386 的数据总线宽度分别为 8 根、8 根、16 根、16 根、32 根。则它们一次可以传送的数据为：<code>1</code>(B)、<code>1</code>(B)、<code>2</code>(B)、<code>2</code>(B)、<code>4</code>(B)。</p><p>(7) 从内存中读取 1024 字节的数据，8086 至少要读 <code>512</code> 次，80386 至少要读 <code>256</code> 次。</p><p>(8) 在存储器中，数据和程序以 <code>二进制</code> 形式存放。</p><h2 id="_1-11-内存地址空间-概述" tabindex="-1">1.11 内存地址空间（概述） <a class="header-anchor" href="#_1-11-内存地址空间-概述" aria-label="Permalink to &quot;1.11 内存地址空间（概述）&quot;">​</a></h2><p>什么是内存地址空间呢?举例来讲，一个 CPU 的地址总线宽度为 10，那么可以寻址 1024 个内存单元，这 <strong>1024 个可寻到的内存单元</strong> 就构成这个 CPU 的 <strong>内存地址空间</strong>。</p><h2 id="_1-12-主板" tabindex="-1">1.12 主板 <a class="header-anchor" href="#_1-12-主板" aria-label="Permalink to &quot;1.12 主板&quot;">​</a></h2><p>在每一台 PC 机中，都有一个主板，主板上有核心器件和一些主要器件，这些器件通过总线（地址总线、数据总线、控制总线）相连。这些器件有 CPU、存储器、外围芯片组、扩展插槽等。扩展插槽上一般插有 RAM 内存条和各类接口卡。</p><h2 id="_1-13-接口卡" tabindex="-1">1.13 接口卡 <a class="header-anchor" href="#_1-13-接口卡" aria-label="Permalink to &quot;1.13 接口卡&quot;">​</a></h2><p>计算机系统中，所有可用程序控制其工作的设备，必须受到 CPU 的控制。CPU 对外部设备都不能直接控制，如显示器、音箱、打印机等。直接控制这些设备进行工作的是插在扩展插槽上的接口卡。扩展插槽通过总线和 CPU 相连，所以接口卡也通过总线同 CPU 相连。CPU 可以 <strong>直接控制这些接口卡</strong>，从而实现 CPU <strong>对外设的间接控制</strong>。简单地讲，就是 CPU 通过总线向接口卡发送命令，接口卡根据 CPU 的命令控制外设进行工作。</p><h2 id="_1-14-各类存储器芯片" tabindex="-1">1.14 各类存储器芯片 <a class="header-anchor" href="#_1-14-各类存储器芯片" aria-label="Permalink to &quot;1.14 各类存储器芯片&quot;">​</a></h2><p>一台 PC 机中, 装有多个存储器芯片, 这些存储器芯片从物理连接上看是独立的、不同的器件。从读写属性上看分为两类: <strong>随机存储器(RAM)</strong> 和 <strong>只读存储器(ROM)</strong>。随机存储器可读可写, 但必须带电存储, 关机后存储的内容丢失; 只读存储器只能读取不能写入, 关机后其中的内容不丢失。这些存储器从功能和连接上又可分为以下几类。</p><ul><li>随机存储器</li></ul><p>用于存放供 CPU 使用的绝大部分程序和数据, 主随机存储器一般由两个位置上的 RAM 组成, 装在主板上 RAM 和插在扩展插槽上的 RAM。</p><ul><li>装有 BIOS(Basic Input/Output System, 基本输入/输出系统)的 ROM</li></ul><p>BIOS 是由主板和各类接口卡(如显卡、网卡等)厂商提供的软件系统, 可以通过它利用该硬件设备进行最基本的输入输出。在主板和某些接口卡上插有存储相应 BIOS 的 ROM。例如, 主板上的 ROM 中存储着主板的 BIOS(通常称为系统 BIOS); 显卡上的 ROM 中存储着显卡的 BIOS; 如果网卡上装有 ROM, 那其中就可以存储网卡的 BIOS。</p><ul><li>接口卡上的 RAM</li></ul><p>某些接口卡需要对大批量输入、输出数据进行暂时存储, 在其上装有 RAM。最典型的是显示卡上的 RAM, 一般称为显存。显示卡随时将显存中的数据向显示器上输出。换句话说, 我们将需要显示的内容写入显存, 就会出现在显示器上。</p><p>图 1.7 展示了 PC 系统中各类存储器的逻辑连接情况。</p><p><img src="'+u+'" alt="image-20251014113202224"></p><h2 id="_1-15-内存地址空间" tabindex="-1">1.15 内存地址空间 <a class="header-anchor" href="#_1-15-内存地址空间" aria-label="Permalink to &quot;1.15 内存地址空间&quot;">​</a></h2><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><p>上述的那些存储器，在物理上是独立的器件，但是在以下两点上相同。</p><ul><li><p>都和 CPU 的总线相连。</p></li><li><p>CPU 对它们进行读或写的时候都通过控制线发出内存读写命令。</p></li></ul><p>这也就是说，CPU 在操控它们的时候，把它们都当作内存来对待，把它们总的看作一个由若干存储单元组成的逻辑存储器，这个逻辑存储器就是我们所说的内存地址空间。在汇编这门课中，我们所面对的是内存地址空间。</p><p>图 1.8 展示了 CPU 将系统中各类存储器看作一个逻辑存储器的情况。</p><p><img src="'+h+`" alt="image-20251014113353657"></p><p>在图 1.8 中, 所有的物理存储器被看作一个由若干存储单元组成的逻辑存储器, 每个物理存储器在这个逻辑存储器中占有一个地址段, 即一段地址空间。CPU 在这段地址空间中读写数据, 实际上就是在相对应的物理存储器中读写数据。</p><p>假设, 图 1.8 中的内存地址空间的地址段分配如下：</p><div class="language-assembly vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">assembly</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>地址 0000H ~ 7FFFH 的 32KB 空间为主随机存储器的地址空间;</span></span>
<span class="line"><span>地址 8000H ~ 9FFFH 的 8KB 空间为显存地址空间;</span></span>
<span class="line"><span>地址 A000H ~ FFFFH 的 24KB 空间为各个ROM的地址空间。</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>这样, CPU 向内存地址为 1000H 的内存单元中写入数据, 这个数据就被写入主随机存储器中; CPU 向内存地址为 8000H 的内存单元中写入数据, 这个数据就被写入显存中, 然后会被显卡输出到显示器上; CPU 向内存地址为 C000H 的内存单元中写入数据的操作是没有结果的, C000H 单元中的内容不会被改变, C000H 单元实际上就是 ROM 存储器中的一个单元。</p><p>内存地址空间的大小受 CPU 地址总线宽度的限制。8086CPU 的地址总线宽度为 20, 可以传送 2^20 个不同的地址信息(大小从 0 至 2^20-1)。即可以定位 2^20 个内存单元, 则 8086PC 的内存地址空间大小为 1MB。同理, 80386CPU 的地址总线宽度为 32, 则内存地址空间最大为 4GB。</p><p>我们在基于一个计算机硬件系统编程的时候, 必须知道这个系统中的内存地址空间分配情况。因为当我们想在某类存储器中读写数据的时候, 必须知道它的第一个单元的地址和最后一个单元的地址, 才能保证读写操作是在预期的存储器中进行。比如, 我们希望向显示器输出一段信息, 那么必须将这段信息写到显存中, 显卡才能将它输出到显示器上。要向显存中写入数据, 必须知道显存在内存地址空间中的地址。</p><p>不同的计算机系统的内存地址空间的分配情况是不同的, 图 1.9 展示了 8086PC 机内存地址空间分配的基本情况。</p><p><img src="`+g+'" alt="image-20251014113837577"></p><p>图 1.9 告诉我们，从地址 0 ~ 9FFFF 的内存单元中读取数据，实际上就是在读取主随机存储器中的数据; 向地址 A0000 ~ BFFFF 的内存单元中写数据, 就是向显存中写入数据, 这些数据会被显示卡输出到显示器上; 我们向地址 C0000 ~ FFFF 的内存单元中写入数据的操作是无效的, 因为这等于改写只读存储器中的内容。</p><blockquote><p>内存地址空间</p><p>最终运行程序的是 CPU，我们用汇编语言编程的时候，必须要从 CPU 的角度考虑问题。对 CPU 来讲，系统中的所有存储器中的存储单元都处于一个统一的逻辑存储器中，它的容量受 CPU 寻址能力的限制。这个逻辑存储器即是我们所说的 <strong>内存地址空间</strong>。</p><p>对于初学者，这个概念比较抽象，后续的课程中将通过一些编程实践，来增加感性认识。</p></blockquote><h2 id="_1-16-cpu-基本组成" tabindex="-1">1.16 CPU 基本组成 <a class="header-anchor" href="#_1-16-cpu-基本组成" aria-label="Permalink to &quot;1.16 CPU 基本组成&quot;">​</a></h2><p>CPU 内部主要由运算器、控制器、寄存器三大部分组成。</p><p><strong>运算器</strong> 负责算术运算（<code>+</code>、<code>-</code>、<code>*</code>、<code>/</code> 基本运算和附加运算）和逻辑运算（包括 移位、逻辑测试或比较两个值等）。</p><p><strong>控制器</strong> 负责应对所有的信息情况，调度运算器把计算做好。</p><p><strong>寄存器</strong> 它们可用来暂存指令、数据和地址。既要对接控制器的命令，传达命令给运算器；还要帮运算器记录处理完或者将要处理的数据。</p><p><img src="'+P+'" alt="CPU 组成"></p><p>内部总线连接各种器件，在它们之间进行数据的传送。可以看一下 8086 的内部结构框图：</p><img src="'+C+'" alt="img" style="zoom:67%;"><h2 id="_1-17-寄存器简介" tabindex="-1">1.17 寄存器简介 <a class="header-anchor" href="#_1-17-寄存器简介" aria-label="Permalink to &quot;1.17 寄存器简介&quot;">​</a></h2><p>这里我们主要来了解一下寄存器，为后面做准备。对于一个汇编程序员来说，CPU 中的主要部件是寄存器。寄存器是 CPU 中程序员可以用指令读写的部件。程序员通过改变各种寄存器中的内容来实现对 CPU 的控制。</p><p>不同的 CPU，寄存器的个数、结构是不相同的。8086CPU 有 14 个寄存器，每个寄存器有一个名称。这些寄存器是：AX、BX、CX、DX、SI、DI、SP、BP、IP、CS、SS、DS、ES、PSW。</p><img src="'+_+'" alt="img" style="zoom:67%;"><h3 id="_1-17-1-通用寄存器组" tabindex="-1">1.17.1 通用寄存器组 <a class="header-anchor" href="#_1-17-1-通用寄存器组" aria-label="Permalink to &quot;1.17.1 通用寄存器组&quot;">​</a></h3><p><strong>数据寄存器</strong>：数据寄存器包括 AX、BX、CX、DX 等 4 个 <strong>16 位寄存器</strong>，主要用来保存算术、逻辑运算的操作数、中间结果和地址。它们既可以作为 16 位寄存器使用，也可以将每个寄存器高字节和低字节分开作为两个独立的 8 位寄存器使用。而 8 位寄存器（AL、BL、CL、DL、AH、BH、CH、DH）只能用于存放数据。</p><p><strong>地址指针和变址寄存器</strong></p><ul><li>地址指针和变址寄存器组包括堆栈指针 SP、堆栈基址寄存器 指针 BP 以及变址寄存器 指针 SI 和 DI 等 4 个 16 位寄存器。它们主要是用来存放或指示操作数的偏移地址。</li><li>堆栈指针 SP 中存放的是当前堆栈段中 <strong>栈顶</strong> 的偏移地址。堆栈操作指令 PUSH 和 POP 就是从 SP 中得到操作数的段内偏移地址的。</li><li>BP 是访问堆栈时的基址寄存器。BP 中存放的是堆栈中某一存储单元的偏移地址，SP、BP 通常和 SS 联用。</li><li><strong>SI 和 DI 称为变址寄存器</strong>。它们通常与 DS 联用，为程序访问当前数据段提供操作数的 <strong>段内</strong> 偏移地址。SI 和 DI 除作为一般的变址寄存器外，在 <strong>串操作指令中 SI 规定用作存放源操作数(即源串)的偏移地址，称为源变址寄存器；DI 规定用作存放目的操作数(目的串)的偏移地址，故称之为目的变址寄存器，二者不能混用</strong>。由于串操作指令规定源字符串必须位于当前数据段 DS 中，目的串必须位于附加段 ES 中，所以 SI 和 DI 中的内容分别是当前数据段和当前附加段中某一存储单元的偏移地址。 当 SI、DI 和 BP 不作指示器和变址寄存器使用时，也可将它们当作一般数据寄存器使用，存放操作数或运算结果。</li></ul><p><strong>隐含寻址</strong></p><ul><li>8 个 16 位通用寄存器在一般情况下都具有通用性。但是，为了缩短指令代码的长度，某些通用寄存器又规定了专门的用途。<strong>隐含寻址就是在指令中隐含地使用了一些通用寄存器，而这些通用寄存器不直接在指令中表现出来 。</strong></li><li>例如，在字符串处理指令中约定必须用 CX 作为 <strong>计数器</strong> 存放串的长度。这样指令中就不必给出 CX 寄存器名，缩短了指令长度，简化了指令的书写形式，这种使用方法称为“隐含寻址”。</li></ul><p>8086 CPU 中通用寄存器的特殊用途和隐含性质</p><img src="'+U+'" alt="img" style="zoom:67%;"><h3 id="_1-17-2-控制寄存器" tabindex="-1">1.17.2 控制寄存器 <a class="header-anchor" href="#_1-17-2-控制寄存器" aria-label="Permalink to &quot;1.17.2 控制寄存器&quot;">​</a></h3><img src="'+q+'" alt="img" style="zoom:67%;"><p>控制标志 控制标志是用来控制 CPU 的工作方式或工作状态的标志。用户可以使用指令设置或清除。</p><p>（1）IF(Interrupt Flag) ——中断允许标志。它是控制可屏蔽中断的标志，如 IF = 1 时，允许 CPU 响应可屏蔽中断；当 IF = 0 时，即使外设有中断申请，CPU 也不响应，即禁止中断。</p><p>（2）DF(Direction Flag) ——方向标志。该标志用来控制串操作指令中地址指针的变化方向。在串操作指令中，若 <strong>DF＝0，地址指针为自动增量</strong>，即由低地址向高地址进行串操作；若 DF＝1，地址指针自动减量，即由高地址向低地址进行串操作。</p><p>（3）TF(Trap Flag)——单步标志。TF＝1 时，CPU 为单步方式，即每执行完一条指令就自动产生一个内部中断，使用户可逐条跟踪程序进行调试。若 TF＝0 时，CPU 正常执行程序。</p><h3 id="_1-17-3-段寄存器组" tabindex="-1">1.17.3 段寄存器组 <a class="header-anchor" href="#_1-17-3-段寄存器组" aria-label="Permalink to &quot;1.17.3 段寄存器组&quot;">​</a></h3><ul><li><p>CS (Code Segment)：代码段寄存器；</p></li><li><p>DS (Data Segment)：数据段寄存器；</p></li><li><p>SS (Stack Segment)：堆栈段寄存器；</p></li><li><p>ES (Extra Segment)：附加段寄存器；</p></li></ul><blockquote><p>参考资料：</p><p><a href="https://cloud.tencent.com/developer/article/2052669" target="_blank" rel="noreferrer">微机原理与接口技术 重点详解与章节总结——8086 微处理器系统结构-腾讯云开发者社区-腾讯云</a></p></blockquote><h2 id="-1" tabindex="-1"><a class="header-anchor" href="#-1" aria-label="Permalink to &quot;&quot;">​</a></h2>',154)])])}const I=e(B,[["render",f]]);export{D as __pageData,I as default};
